import { createTask, getTasks, triggerJob } from "wasp/client/operations";
import "./Main.css";

export function MainPage() {
  const [description, setDescription] = useState("");
  const { data: tasks, isLoading, error } = useQuery(getTasks);
  const createTaskAction = useAction(createTask);
  const triggerJobAction = useAction(triggerJob);

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedDescription = description.trim();
    if (!trimmedDescription) {
      return;
    }

    await createTaskAction({ description: trimmedDescription });
    setDescription("");
  };

  const handleTriggerJob = async () => {
    await triggerJobAction();
  };

  return (
    <main className="container">
      <section className="card">
        <h1 className="title">Background Tasks</h1>
        <p className="subtitle">
          Create tasks, then trigger the background job to mark them as processed.
        </p>

        <form className="task-form" onSubmit={handleSubmit}>
          <input
            className="task-input"
            type="text"
            value={description}
            placeholder="Describe a task"
            onChange={(event) => setDescription(event.target.value)}
          />
          <button className="button button-primary" type="submit">
            Add Task
          </button>
        </form>

        <button className="button button-secondary" onClick={handleTriggerJob}

