    -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen", "Ubuntu",
    "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  background: #f5f6fb;
  color: #1f2937;
}

#root {
  min-height: 100vh;
}

.container {
  max-width: 900px;
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.card {
  background: #ffffff;
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.08);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.title {
  font-size: 2.2rem;
  font-weight: 700;
}

.subtitle {
  color: #475569;
  font-size: 1rem;
  line-height: 1.6;
}

.task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.task-input {
  flex: 1;
  min-width: 200px;
  padding: 0.75rem 1rem;
  border-radius: 10px;
  border: 1px solid #cbd5f5;
  font-size: 1rem;
}

.button {
  border: none;
  border-radius: 10px;
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.button:active {
  transform: scale(0.98);
}

.button-primary {
  background: #4f46e5;
  color: #ffffff;
}

.button-secondary {
  background: #e0e7ff;
  color: #3730a3;
  align-self: flex-start;
}

.task-list ul {
  list-style: none;

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

